from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool

n = 27
N = 2*n
vpool = IDPool()
# x[v][i] = value v placed starting at position i (1..N), second occurrence at i+v+1
# Wait: "v+1 positions apart" - copies of 1 are 1 position apart means adjacent.
# Example L(2,3): [2,3,1,2,1,3] - positions of 1: 3,5 (diff 2), positions of 2: 1,4 (diff 3), positions of 3: 2,6 (diff 4).
# So two copies of v are at distance v+1.

def x(v,i): return vpool.id(('x',v,i))
def y(p,v): return vpool.id(('y',p,v))  # position p has value v

clauses = []
# Each value placed exactly once
for v in range(1,n+1):
    lits = []
    for i in range(1, N - v):  # i and i+v+1 both <= N
        if i + v + 1 <= N:
            lits.append(x(v,i))
    # exactly one
    clauses.append(lits)
    for a in range(len(lits)):
        for b in range(a+1,len(lits)):
            clauses.append([-lits[a],-lits[b]])

# Each position gets exactly one value (via link to x)
# For each position p, collect which (v,i) place a value there
pos_lits = {p: [] for p in range(1,N+1)}
for v in range(1,n+1):
    for i in range(1,N+1):
        if i+v+1 <= N:
            pos_lits[i].append(x(v,i))
            pos_lits[i+v+1].append(x(v,i))

for p in range(1,N+1):
    lits = pos_lits[p]
    clauses.append(lits)  # at least one
    for a in range(len(lits)):
        for b in range(a+1,len(lits)):
            clauses.append([-lits[a],-lits[b]])

s = Glucose3()
for c in clauses:
    s.add_clause(c)

print(s.solve())
m = s.get_model()
mset = set(m)
seq = [0]*(N+1)
for v in range(1,n+1):
    for i in range(1,N+1):
        if i+v+1 <= N and x(v,i) in mset:
            seq[i] = v
            seq[i+v+1] = v
print(seq[1:])
